"""
Pages Batch 14 (Canvases 101-105, Orig. pp. 63-67) for Wellcome MS.244.
Covers surgical and medical receipts for wounds, sores, plasters, bleeding, and harelips:
  - Canvas 101 (p. 63): Plasters, cerecloths, green salve, Emplastrum Dingley, Gratia Dei & Melilot
  - Canvas 102 (p. 64): Wound drinks, festers & fistulas, Potus Angelicus, vulnerary potions
  - Canvas 103 (p. 65): Bleeding of green wounds to stop, Lanfranc's styptics & frog-spawn linen
  - Canvas 104 (p. 66): Bleeding at the nose, toad amulets, astringents & Dr. John Sadler's pills
  - Canvas 105 (p. 67): Staunching bleeding, pomander, linseed oil, harelip surgery (with knot diagrams), Lady Mary Grey's receipt
"""


def make_lines(prefix, canvas_num, col_id, ulx, uly, lrx, lry, line_tuples):
    n = len(line_tuples)
    step = (lry - uly) / max(1, n)
    img_svc = f"https://iiif.wellcomecollection.org/image/b19608652_MS_244_{canvas_num:04d}.JP2"
    canvas_uri = f"https://iiif.wellcomecollection.org/presentation/b19608652/canvases/b19608652_MS_244_{canvas_num:04d}.JP2"
    out = []
    for idx, (lno, ltype, orig_text, en_text, note) in enumerate(line_tuples):
        y0 = int(round(uly + idx * step))
        y1 = int(round(uly + (idx + 1) * step))
        w = lrx - ulx
        h = y1 - y0
        xywh = f"{ulx},{y0},{w},{h}"
        line_id = f"{prefix}_{col_id}_l{lno:02d}" if isinstance(lno, int) else f"{prefix}_{col_id}_{lno}"
        out.append({
            "line_id": line_id,
            "line_num": str(lno),
            "line_type": ltype,
            "ulx": ulx,
            "uly": y0,
            "lrx": lrx,
            "lry": y1,
            "xywh": xywh,
            "iiif_canvas_xywh": f"{canvas_uri}#xywh={xywh}",
            "iiif_image_crop": f"{img_svc}/{xywh}/full/0/default.jpg",
            "orig": orig_text,
            "en": en_text,
            "note": note,
        })
    return out


